/* Splits the CH_ASSETS object into separately loaded bundles (R7).
     data/assets.js         core: everything not listed below, plus meta and music paths
     data/bundle_heroes.js  img keys 'hero.*'
     data/bundle_bosses.js  img keys 'boss.*'
     data/bundle_audio.js   sfx + loops
     data/bundle_ui.js, data/bundle_sidekicks.js  empty slots, filled by pack-ui / pack-sidekicks
   Every bundle merges itself into window.CH_ASSETS, so each one is optional.
   CLI: `node tools/split-bundles.js` re-splits whatever is in data/ (idempotent). */
const fs = require('fs');
const path = require('path');

const OUT = path.resolve(__dirname, '..', 'data');
const KINDS = ['img', 'sfx', 'loops', 'music', 'meta'];
const PRELUDE =
  'window.CH_ASSETS=window.CH_ASSETS||{img:{},sfx:{},loops:{},music:{},meta:{}};' +
  '(function(a,W){for(var k in a){W[k]=W[k]||{};for(var i in a[k])W[k][i]=a[k][i];}})(';
const POSTLUDE = ',window.CH_ASSETS);\n';

/* bundle name -> predicate on (kind, key) */
const BUNDLES = {
  assets: () => true, // core is the catch-all and keeps the historical file name
  heroes: (kind, key) => kind === 'img' && key.startsWith('hero.'),
  bosses: (kind, key) => kind === 'img' && key.startsWith('boss.'),
  audio: (kind) => kind === 'sfx' || kind === 'loops',
  ui: (kind, key) => kind === 'img' && key.startsWith('ui.'),
  sidekicks: (kind, key) => kind === 'img' && key.startsWith('sk.'),
  sheets: (kind, key) => kind === 'img' && key.startsWith('sh.'),
};
const ORDER = ['heroes', 'bosses', 'audio', 'ui', 'sidekicks', 'sheets', 'assets'];
const fileOf = (name) => path.join(OUT, name === 'assets' ? 'assets.js' : 'bundle_' + name + '.js');

function splitBundles(all) {
  const parts = {};
  for (const n of Object.keys(BUNDLES)) parts[n] = {};
  for (const kind of KINDS) {
    for (const key of Object.keys(all[kind] || {})) {
      const owner = ORDER.find((n) => n !== 'assets' && BUNDLES[n](kind, key)) || 'assets';
      (parts[owner][kind] = parts[owner][kind] || {})[key] = all[kind][key];
    }
  }
  const sizes = {};
  fs.mkdirSync(OUT, { recursive: true });
  for (const n of Object.keys(parts)) {
    const js = '/* GENERATED by tools/split-bundles.js - do not edit. Bundle: ' + n + ' */\n' + PRELUDE + JSON.stringify(parts[n]) + POSTLUDE;
    fs.writeFileSync(fileOf(n), js);
    sizes[n] = js.length;
  }
  return sizes;
}

function loadAll() {
  const merged = {};
  for (const n of Object.keys(BUNDLES)) {
    const f = fileOf(n);
    if (!fs.existsSync(f)) continue;
    const sandbox = { window: {} };
    new Function('window', fs.readFileSync(f, 'utf8'))(sandbox.window);
    const a = sandbox.window.CH_ASSETS || {};
    for (const k of Object.keys(a)) Object.assign((merged[k] = merged[k] || {}), a[k]);
  }
  return merged;
}

module.exports = { splitBundles, loadAll, BUNDLES, ORDER, fileOf };

if (require.main === module) {
  const sizes = splitBundles(loadAll());
  for (const n of Object.keys(sizes)) console.log(n.padEnd(10), (sizes[n] / 1048576).toFixed(2) + ' MB');
}
